:flex;gap:8px;pointer-events:auto}.action{border:1px solid #5d7778;background:rgba(8,16,19,.82);color:#dfe9e7;min-width:76px;height:54px;padding:7px 10px;font-family:Rajdhani;font-weight:700;text-transform:uppercase;cursor:pointer}.action b{display:block;font-size:13px}.action span{display:block;font-size:9px;color:#91a6a5}.action.primary{border-color:#72ccd5;color:#c8fcff}.action.danger{border-color:#a74d48;color:#ffafa7}.action:disabled{opacity:.35}.prompt{position:absolute;left:50%;bottom:94px;transform:translateX(-50%);background:rgba(5,12,14,.88);border-left:3px solid var(--cyan);padding:8px 13px;font-size:12px;opacity:0;transition:.15s}.prompt.show{opacity:1}.crosshair{position:absolute;left:50%;top:50%;width:12px;height:12px;transform:translate(-50%,-50%);border:1px solid rgba(255,255,255,.55);border-radius:50%}.crosshair:before,.crosshair:after{content:'';position:absolute;background:rgba(255,255,255,.7)}.crosshair:before{width:18px;height:1px;left:-4px;top:5px}.crosshair:after{height:18px;width:1px;top:-4px;left:5px}.menu{position:absolute;inset:0;background:rgba(4,9,11,.78);display:flex;align-items:center;justify-content:center;pointer-events:auto}.menu.hidden{display:none}.card{width:min(520px,calc(100% - 40px));border:1px solid #526769;background:rgba(8,15,17,.96);padding:30px;box-shadow:0 25px 100px #000}.kicker{color:var(--orange);letter-spacing:4px;font-size:11px}.card h1{font:38px 'Black Ops One';margin:8px 0 4px}.card p{color:#a9baba;margin:6px 0 18px}.card button{background:var(--cyan);border:0;color:#071014;height:48px;padding:0 24px;font:700 14px Rajdhani;letter-spacing:1px;cursor:pointer}.card button.red{background:#ee6961;color:#fff}.touch{display:none}.touchzone{position:absolute;bottom:88px;width:130px;height:130px;left:14px;border:1px solid rgba(145,201,202,.18);border-radius:50%;pointer-events:auto}.stick{position:absolute;width:48px;height:48px;border-radius:50%;left:41px;top:41px;background:rgba(130,200,202,.18);border:1px solid rgba(180,240,240,.35)}@media(max-width:700px){.objective{top:64px;transform:scale(.82);transform-origin:left top}.players{top:64px;transform:scale(.82);transform-origin:right top}.topbar{left:10px;right:10px}.brand{font-size:14px}.score{top:67px}.actions{bottom:10px}.action{min-width:62px;height:48px}.prompt{bottom:66px}.touch{display:block}.crosshair{display:none}}
