<body>
<canvas id="c"></canvas><div class="hud"><div class="topbar"><div class="brand">DE_<b>IMPOSTOR</b></div><div class="score"><div class="team blue"><strong id="blueScore">0</strong><span>CREW</span></div><div class="slash">/</div><div class="team red"><strong id="redScore">0</strong><span>IMPOSTOR</span></div></div><div class="roundbox"><div class="mapname">DE_DUSK // ROUND 1</div><div class="timer"><em>ROUND</em><span id="time">01:45</span></div></div></div>
<div class="objective"><h3>OBJECTIVES</h3><div class="objline"><i class="dot" id="d1"></i><span id="o1">Restore generator</span></div><div class="objline"><i class="dot" id="d2"></i><span id="o2">Upload crew manifest</span></div><div class="objline"><i class="dot" id="d3"></i><span id="o3">Complete 3 scans</span></div></div><div class="players"><h3>ROUND STATUS</h3><div id="roster"></div></div><div class="crosshair"></div><div class="prompt" id="prompt">E — USE TERMINAL</div><div class="actions"><button class="action primary" id="use"><b>USE</b><span>[ E ]</span></button><button class="action danger" id="kill"><b>KILL</b><span>[ Q ]</span></button><button class="action" id="report"><b>REPORT</b><span>[ R ]</span></button></div><div class="touch"><div class="touchzone" id="zone"><div class="stick" id="stick"></div></div></div></div>
<div class="menu" id="menu"><div class="card"><div class="kicker">ROUND 01 // DE_DUSK</div><h1 id="menutitle">CREWMATE ASSIGNMENT</h1><p id="menutext">Complete objectives and identify the red impostor before he eliminates the team.</p><button id="start">DEPLOY</button></div></div>
<script>
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');let W,H,DPR;function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const keys={};addEventListener('keydown',e=>{keys[e.key.toLower=e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='e')use();if(e.key.toLowerCase()==='q')kill();if(e.key.toLowerCase()==='r')report();});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
let running=false,round=105,time=105,scoreB=0,scoreR=0,scan=0,won=false,flash=0,meeting=false,killCd=0;
const player={x:0,y:-100,r:12,angle:0,flash:0};const impostor={x:-270,y:-30,r:13,alive:true,flash:0};const roster=[{name:'YOU',blue:true,alive:true},{name:'KILLJOY',blue:true,alive:true},{name:'SAGE',blue:true,alive:true},{name:'PHOENIX',blue:false,alive:true},{name:'RADIANT',blue:true,alive:true}];
const walls=[[-430,-250,-340,-250,-340,-50,-430,-50],[-430,-250,-430,180,-380,180,-380,-250],[340,-250,430,-250,430,180,380,180,380,-250],[-180,-250,-180,-145,-80,-145,-80,-250],[80,-250,80,-145,180,-145,180,-250],[260,-30,430,-30,430,30,260,30],[-430,-30,-260,-30,-260,30,-430,30],[-180,80,-80,80,-80,180,-180,180]];
const stations=[{x:-350,y:-150,n:'GENERATOR',task:'d1',done:false},{x:350,y:130,n:'UPLOAD',task:'d2',done:false},{x:0,y:-190,n:'SCAN',task:'d3',done:false},{x:0,y:130,n:'MED BAY',task:'d3',done:false},{x:-350,y:130,n:'CARGO',task:'scan',done:false}];
function reset(){round++;time=105;scan=0;won=false;meeting=false;killCd=0;player.x=0;player.y=90;impostor.x=-270;impostor.y=-30;impostor.alive=true;stations.forEach(s=>s.done=false);roster.forEach((p,i)=>p.alive=i!==4);renderRoster();}
function worldToScreen(x,y){return {x:W/2+x,y:H/2+y}}function isWall(nx,ny){for(const w of walls){let x=[];for(let i=0;i<w.length;i+=2)x.push([w[i],w[i+1]]);if(pointPoly(nx,ny,x))return true}return Math.abs(nx)>410||Math.abs(ny)>240}
function pointPoly(x,y,v){let c=false;for(let i=0,j=v.length-1;i<v.length;j=i++){let xi=v[i][0],yi=v[i][1],xj=v[j][0],yj=v[j][1];if(((yi>y)!=(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi))c=!c}return c}
function movePlayer(){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);let n=Math.hypot(dx,dy)||1;dx=dx/n*2.25;dy=dy/n*2.25;if(!isWall(player.x+dx,player.y))player.x+=dx;if(!isWall(player.x,player.y+dy))player.y+=dy;if(dx||dy)player.angle=Math.atan2(dy,dx)}
let touchDX=0,touchDY=0;const zone=document.getElementById('zone'),stick=document.getElementById('stick');function touchMove(e){e.prevent.preventDefault();let r=zone.getBoundingClientRect(),t=e.touches[0],dx=t.clientX-(r.left+r.width/2),dy=t.clientY-(r.top+r.height/2),m=Math.max(r.width/2,Math.hypot(dx,dy));touchDX=dx/m;touchDY=dy/m;stick.style.transform=`translate(${touchDX*38}px,${touchDY*38}px)`}zone&&zone.addEventListener('touchstart',touchMove,{passive:false});zone&&zone.addEventListener('touchmove',touchMove,{passive:false});zone&&zone.addEventListener('touchend',()=>{touchDX=touchDY=0;stick.style.transform=''});
function use(){if(!running||meeting)return;for(const s of stations){if(Math.hypot(player.x-s.x,player.y-s.y)<38&&!s.done){s.done=true;flash=12;if(s.task==='d1')document.getElementById('d1').className='dot done';if(s.task==='d2')document.getElementById('d2').className='dot done';if(s.task==='d3'){scan++;if(scan>=3)document.getElementById('d3').className='dot done'}return}}promptNear()}
function kill(){if(!running||meeting||killCd>0)return;killCd=260;if(Math.hypot(player.x-impostor.x,player.y-impostor.y)<55&&impostor.alive){impostor.alive=false;scoreB++;document.getElementById('blueScore').textContent=scoreB;end(true,'IMPOSTOR ELIMINATED','The crew secured the site. All objectives remain under control.')}}
function report(){if(!running)return;meeting=true;running=false;const card=document.getElementById('menu'),title=document.getElementById('menutitle'),text=document.getElementById('menutext'),btn=document.getElementById('start');card.classList.remove('hidden');title.textContent='EMERGENCY MEETING';text.textContent='Vote: identify the red impostor. A correct vote ends the round.';btn.textContent='VOTE OUT RED';btn.className='red';btn.onclick=()=>{meeting=false;card.classList.add('hidden');scoreB++;document.getElementById('blueScore').textContent=scoreB;end(true,'CREW VICTORY','The suspected player was removed. The operation is secure.')}}
function promptNear(){let found=false;for(const s of stations)if(!s.done&&Math.hypot(player.x-s.x,player.y-s.y)<48){found=true}document.getElementById('prompt').className='prompt'+(found?' show':'')}
function end(win,title,text){won=win;running=false;const card=document.getElementById('menu');card.classList.remove('hidden');document.getElementById('menutitle').textContent=title;document.getElementById('menutext').textContent=text;const btn=document.getElementById('start');btn.textContent='NEXT ROUND';btn.className='';btn.onclick=()=>{card.classList.add('hidden');reset();running=true}}
function renderRoster(){let el=document.getElementById('roster');el.innerHTML=roster.map(p=>`<div class="alive"><span>${p.name}</span><i class="avatar ${p.blue?'':'red'} ${p.alive?'':'dead'}"></i></div>`).join('')}
function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#10191b';ctx.fillRect(0,0,W,H);let grid=42;ctx.strokeStyle='rgba(91,120,121,.12)';ctx.lineWidth=1;for(let x=(W/2-player.x)%grid;x<W;x+=grid){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=(H/2-player.y)%grid;y<H;y+=grid){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}drawFloor();for(const w of walls)drawWall(w);for(const s of stations)drawStation(s);if(impostor.alive)drawPerson(worldToScreen(impostor.x,impostor.y).x,worldToScreen(impostor.x,impostor.y).y,'#e44e46',impostor.angle, true);drawPerson(worldToScreen(player.x,player.y).x,worldToScreen(player.x,player.y).y,'#55c6d4',player.angle,false);if(flash>0){ctx.fillStyle=`rgba(103,217,232,${flash/40})`;ctx.fillRect(0,0,W,H);flash--}}
function drawFloor(){ctx.save();ctx.translate(W/2,H/2);ctx.rotate(-.02);ctx.fillStyle='#1a2425';ctx.fillRect(-390,-220,780,440);ctx.strokeStyle='rgba(161,185,181,.09)';ctx.lineWidth=1;for(let x=-390;x<390;x+=55){ctx.beginPath();ctx.moveTo(x,-220);ctx.lineTo(x,220);ctx.stroke()}for(let y=-220;y<220;y+=55){ctx.beginPath();ctx.moveTo(-390,y);ctx.lineTo(390,y);ctx.stroke()}ctx.fillStyle='rgba(110,190,190,.035)';ctx.fillRect(-390,-220,780,440);ctx.restore()}
function drawWall(w){ctx.beginPath();ctx.moveTo(worldToScreen(w[0],w[1]).x,worldToScreen(w[0],w[1]).y);for(let i=2;i<w.length;i+=2)ctx.lineTo(worldToScreen(w[i],w[i+1]).x,worldToScreen(w[i],w[i+1]).y);ctx.closePath();ctx.fillStyle='#263436';ctx.fill();ctx.strokeStyle='#759092';ctx.lineWidth=2;ctx.stroke();ctx.strokeStyle='rgba(0,0,0,.45)';ctx.lineWidth=5;ctx.stroke()}
function drawStation(s){let p=worldToScreen(s.x,s.y);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=s.done?'#1f6a69':'#7a5f45';ctx.fillRect(-18,-12,36,24);ctx.fillStyle=s.done?'#67d9e8':'#b99264';ctx.fillRect(-12,-8,24,16);ctx.fillStyle='#111';ctx.fillRect(-8,-5,16,3);ctx.restore()}
function drawPerson(x,y,c,ang,enemy){ctx.save();ctx.translate(x,y);ctx.rotate(ang);ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(2,13,16,7,0,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(0,0,14,18,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bce4df';ctx.beginPath();ctx.roundRect(1,-11,14,7,3);ctx.fill();ctx.fillStyle='#263b3d';ctx.fillRect(-12,-17,24,4);ctx.fillStyle='#071011';ctx.beginPath();ctx.arc(-17,5,5,0,7);ctx.fill();ctx.restore();if(enemy){ctx.fillStyle='#ff7168';ctx.font='700 9px Rajdhani';ctx.textAlign='center';ctx.fillText('IMPOSTOR',x,y-30)}}
function ai(){if(!impostor.alive||!running)return;let dx=player.x-impostor.x,dy=player.y-impostor.y,d=Math.hypot(dx,dy);if(d>65){let nx=impostor.x+(dx/d)*.72,ny=impostor.y+(dy/d)*.72;if(!isWall(nx,impostor.y))impostor.x=nx;if(!isWall(impostor.x,ny))impostor.y=ny;impostor.angle=Math.atan2(dy,dx)}else if(killCd<=0){killCd=190;player.flash=10;scoreR++;document.getElementById('redScore').textContent=scoreR;end(false,'CREWMATE ELIMINATED','The impostor got close. Report the threat and watch your six.')}}
function tick(){if(running){movePlayer();if(touchDX||touchDY){let nx=player.x+touchDX*2.2,ny=player.y+touchDY*2.2;if(!isWall(nx,player.y))player.x=nx;if(!isWall(player.x,ny))player.y=ny;player.angle=Math.atan2(touchDY,touchDX)}ai();if(killCd>0)killCd--;time-=1/60;if(time<=0){scoreB++;document.getElementById('blueScore').textContent=scoreB;end(true,'TIME COMPLETE','The round was secured before the timer expired.')}let m=Math.floor(time/60),s=Math.floor(time%60);document.getElementById('time').textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');let complete=stations.filter(s=>s.done&&s.task==='d1').length&&stations.filter(s=>s.done&&s.task==='d2').length&&(scan>=3);if(complete&&scan>=3){scoreB++;document.getElementById('blueScore').textContent=scoreB;end(true,'OBJECTIVES COMPLETE','All critical systems restored. The impostor has been contained.')}promptNear()}draw();requestAnimationFrame(tick)}renderRoster();document.getElementById('use').onclick=use;document.getElementById('kill').onclick=kill;document.getElementById('report').onclick=report;document.getElementById('start').onclick=()=>{document.getElementById('menu').classList.add('hidden');reset();running=true};tick();
</script></body></html>
